import Ajv from 'ajv'
import { createHash } from 'node:crypto'
import type { ProviderDispatchReceipt } from './providerDispatchFetch'

/** Pure accounting policy only. No execution capabilities, goal budgets, IPC,
 * provider calls, persistent storage or restart authority are supplied here.
 * IDs/bindings below MUST eventually be captured/generated by a trusted main
 * admission layer; a structurally valid command is not permission to execute. */
export const DISPATCH_LEDGER_LIMITS = Object.freeze({ runs: 4, attempts: 32, receipts: 264, plainBytes: 128 * 1024, settlementHeadroom: 16 * 1024, maxWalltimeMs: 30 * 60 * 1000, responseBytes: 64 * 1024 * 1024 })
export type DispatchLedgerBinding = { goalId: string; generation: number; profileHash: string }
export type DispatchLedgerRun = {
  id: string; binding: DispatchLedgerBinding; status: 'active' | 'finished' | 'unknown'
  startedAt: number; updatedAt: number; deadlineAt: number
  maxProviderDispatches: number; chargedProviderDispatches: number
  attempts: Array<{ id: string; reservedAt: number; settledAt?: number; outcome?: ProviderDispatchReceipt }>
}
export type DispatchLedgerOperationReceipt = { action: DispatchLedgerCommand['action']; operationHash: string; digest: string; revision: number; runId: string; attemptId?: string }
export type DispatchLedgerDocument = { version: 1; ownerHash: string; revision: number; runs: DispatchLedgerRun[]; receipts: DispatchLedgerOperationReceipt[] }
export type DispatchLedgerCommand = { operationId: string; expectedRevision: number } & (
  | { action: 'begin'; runId: string; binding: DispatchLedgerBinding; maxProviderDispatches: number; maxWalltimeMs: number }
  | { action: 'reserve'; runId: string; attemptId: string }
  | { action: 'settle'; runId: string; attemptId: string; outcome: ProviderDispatchReceipt }
  | { action: 'finish'; runId: string }
  | { action: 'orphan'; runId: string }
)
const L = DISPATCH_LEDGER_LIMITS
const object = (properties: Record<string, unknown>, required = Object.keys(properties)) => ({ type: 'object', additionalProperties: false, properties, required })
const integer = (minimum = 0, maximum = Number.MAX_SAFE_INTEGER) => ({ type: 'integer', minimum, maximum })
const uuid = { type: 'string', pattern: '^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' }
const hash = { type: 'string', pattern: '^[a-f0-9]{64}$' }
const binding = object({ goalId: uuid, generation: integer(1), profileHash: hash })
const outcome = { oneOf: [
  object({ state: { enum: ['not-dispatched', 'unknown'] }, charged: { const: true }, grantsPermission: { const: false } }),
  object({ state: { const: 'response-complete' }, status: integer(200, 599), responseBytes: integer(0, L.responseBytes), charged: { const: true }, grantsPermission: { const: false } })
] }
const attempt = object({ id: uuid, reservedAt: integer(), settledAt: integer(), outcome }, ['id', 'reservedAt'])
const run = object({ id: uuid, binding, status: { enum: ['active', 'finished', 'unknown'] }, startedAt: integer(), updatedAt: integer(), deadlineAt: integer(), maxProviderDispatches: integer(1, L.attempts), chargedProviderDispatches: integer(0, L.attempts), attempts: { type: 'array', maxItems: L.attempts, items: attempt } })
const receipt = object({ action: { enum: ['begin', 'reserve', 'settle', 'finish', 'orphan'] }, operationHash: hash, digest: hash, revision: integer(1, L.receipts), runId: uuid, attemptId: uuid }, ['action', 'operationHash', 'digest', 'revision', 'runId'])
const ajv = new Ajv({ strict: true, ownProperties: true })
const validDocument = ajv.compile(object({ version: { const: 1 }, ownerHash: hash, revision: integer(0, L.receipts), runs: { type: 'array', maxItems: L.runs, items: run }, receipts: { type: 'array', maxItems: L.receipts, items: receipt } }))
const fields = {
  begin: { binding, maxProviderDispatches: integer(1, L.attempts), maxWalltimeMs: integer(1, L.maxWalltimeMs) },
  reserve: { attemptId: uuid }, settle: { attemptId: uuid, outcome }, finish: {}, orphan: {}
}
const commands = new Map(Object.entries(fields).map(([action, props]) => [action, ajv.compile(object({ action: { const: action }, operationId: uuid, expectedRevision: integer(0, L.receipts - 1), runId: uuid, ...props }))]))
const sha = (value: unknown) => createHash('sha256').update(JSON.stringify(value)).digest('hex')
function canonical(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonical)
  if (value && typeof value === 'object') return Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical((value as Record<string, unknown>)[key])]))
  return value
}
function reject(reason: string): never { throw new Error(`Dispatch ledger ${reason}.`) }
export function emptyDispatchLedger(ownerHash: string): DispatchLedgerDocument {
  const value: DispatchLedgerDocument = { version: 1, ownerHash, revision: 0, runs: [], receipts: [] }; validateDispatchLedger(value); return value
}
export function validateDispatchLedger(value: unknown): asserts value is DispatchLedgerDocument {
  if (!validDocument(value) || Buffer.byteLength(JSON.stringify(value), 'utf8') > L.plainBytes) reject('schema or byte capacity invalid')
  const doc = value as DispatchLedgerDocument
  if (doc.receipts.length !== doc.revision || new Set(doc.receipts.map(item => item.operationHash)).size !== doc.receipts.length || doc.receipts.some((item, i) => item.revision !== i + 1) || new Set(doc.runs.map(item => item.id)).size !== doc.runs.length || doc.runs.filter(item => item.status !== 'finished').length > 1) reject('identity, receipt or lifetime invariants invalid')
  const allAttempts = doc.runs.flatMap(item => item.attempts.map(attempt => attempt.id))
  if (new Set(allAttempts).size !== allAttempts.length || doc.receipts.some(item => !doc.runs.some(run => run.id === item.runId && (!item.attemptId || run.attempts.some(attempt => attempt.id === item.attemptId))))) reject('retained operation identities invalid')
  let priorRunUpdated = 0
  const observed = new Map<string, { status: DispatchLedgerRun['status']; pending?: string; attempts: string[] }>()
  let liveRun: string | undefined, permanentlyFenced = false
  for (const receipt of doc.receipts) {
    let state = observed.get(receipt.runId)
    const record = doc.runs.find(run => run.id === receipt.runId)!
    if ((['reserve', 'settle'].includes(receipt.action)) !== Boolean(receipt.attemptId)) reject('receipt action identity invalid')
    if (receipt.action === 'begin') {
      if (state || liveRun || permanentlyFenced) reject('duplicate, overlapping or uncertain begin receipt')
      state = { status: 'active', attempts: [] }; observed.set(receipt.runId, state); liveRun = receipt.runId
    } else {
      if (!state || state.status !== 'active' || liveRun !== receipt.runId) reject('receipt after terminal or before begin')
      if (receipt.action === 'reserve') {
        if (state.pending || state.attempts.includes(receipt.attemptId!)) reject('receipt bypasses pending fence')
        state.pending = receipt.attemptId; state.attempts.push(receipt.attemptId!)
      } else if (receipt.action === 'settle') {
        if (state.pending !== receipt.attemptId) reject('receipt settles wrong reservation')
        const attempt = record.attempts.find(item => item.id === receipt.attemptId)!
        if (!attempt.outcome) reject('settlement receipt missing outcome')
        if (attempt.outcome.state === 'unknown') state.status = 'unknown'
        delete state.pending
      } else {
        if (receipt.action === 'orphan' && state.pending && record.attempts.find(item => item.id === state!.pending)?.outcome?.state !== 'unknown') reject('orphan receipt lost pending uncertainty')
        if (receipt.action === 'finish' && state.pending) reject('finish receipt with pending reservation')
        state.status = receipt.action === 'finish' ? 'finished' : 'unknown'; delete state.pending
      }
      if (state.status !== 'active') { liveRun = undefined; if (state.status === 'unknown') permanentlyFenced = true }
    }
  }
  for (const run of doc.runs) {
    const state = observed.get(run.id)
    if (!state || state.status !== run.status || JSON.stringify(state.attempts) !== JSON.stringify(run.attempts.map(item => item.id)) || state.pending !== run.attempts.find(item => !item.outcome)?.id || run.startedAt < priorRunUpdated) reject('record does not match retained transition receipts')
    priorRunUpdated = run.updatedAt
    if (run.deadlineAt <= run.startedAt || run.deadlineAt - run.startedAt > L.maxWalltimeMs || run.updatedAt < run.startedAt || run.chargedProviderDispatches !== run.attempts.length || run.chargedProviderDispatches > run.maxProviderDispatches) reject('charged counters or original deadline invalid')
    let previous = run.startedAt, pending = 0, unknown = 0
    for (const attempt of run.attempts) {
      if (attempt.reservedAt < previous || attempt.reservedAt >= run.deadlineAt || attempt.reservedAt > run.updatedAt || Boolean(attempt.outcome) !== (attempt.settledAt !== undefined) || attempt.settledAt !== undefined && (attempt.settledAt < attempt.reservedAt || attempt.settledAt > run.updatedAt)) reject('attempt chronology invalid')
      previous = attempt.settledAt ?? attempt.reservedAt
      if (!attempt.outcome) pending++
      else if (attempt.outcome.state === 'unknown') unknown++
      else if (attempt.outcome.state === 'response-complete' && attempt.outcome.status >= 300 && attempt.outcome.status < 400) reject('redirect receipt unsupported')
      if ((pending || unknown) && attempt !== run.attempts.at(-1)) reject('dispatch after uncertain attempt invalid')
    }
    if (run.status === 'active' && (doc.receipts.length + (pending ? 2 : 1) > L.receipts || Buffer.byteLength(JSON.stringify(doc), 'utf8') > L.plainBytes - L.settlementHeadroom)) reject('active reservation settlement headroom invalid')
    if (pending > 1 || run.status === 'finished' && (pending || unknown) || run.status === 'active' && unknown || run.status === 'unknown' && pending) reject('uncertainty fence invalid')
  }
}
/** Data-only replay result: NEVER an authority/capability to send. All receipts
 * are retained. Exhaustion refuses new work rather than forgetting replay IDs.
 * No settlement erases charges; no orphan/unknown transition can be reversed.
 * modelSteps/toolCalls are deliberately not implemented or aliased to this unit. */
export function applyDispatchLedger(document: DispatchLedgerDocument, command: DispatchLedgerCommand, now: number): { document: DispatchLedgerDocument; receipt: DispatchLedgerOperationReceipt; replay: boolean } {
  validateDispatchLedger(document)
  if (!commands.get(command?.action)?.(command)) reject('command invalid')
  const operationHash = sha([document.ownerHash, command.operationId]), digest = sha(canonical(command))
  const prior = document.receipts.find(item => item.operationHash === operationHash)
  if (prior) {
    if (prior.digest !== digest || prior.revision !== command.expectedRevision + 1 || prior.action !== command.action || prior.runId !== command.runId || prior.attemptId !== ('attemptId' in command ? command.attemptId : undefined)) reject('operation replay conflict')
    return { document: structuredClone(document), receipt: structuredClone(prior), replay: true }
  }
  if (!Number.isSafeInteger(now) || now < 0 || command.expectedRevision !== document.revision) reject('clock or revision conflict')
  if (document.revision >= L.receipts) reject('receipt capacity exhausted')
  const next = structuredClone(document)
  let current = next.runs.find(item => item.id === command.runId)
  if (command.action === 'begin') {
    if (current || next.runs.some(item => item.status !== 'finished')) reject('scope is active, orphaned or uncertain')
    if (now < (next.runs.at(-1)?.updatedAt ?? 0)) reject('clock moved backwards across runs')
    if (next.runs.length >= L.runs || next.receipts.length + 2 > L.receipts || now > Number.MAX_SAFE_INTEGER - command.maxWalltimeMs) reject('run capacity or deadline exhausted')
    current = { id: command.runId, binding: structuredClone(command.binding), status: 'active', startedAt: now, updatedAt: now, deadlineAt: now + command.maxWalltimeMs, maxProviderDispatches: command.maxProviderDispatches, chargedProviderDispatches: 0, attempts: [] }
    next.runs.push(current)
  } else {
    if (!current || current.status !== 'active' || now < current.updatedAt) reject('run is unavailable, uncertain or clock moved backwards')
    const pending = current.attempts.find(item => !item.outcome)
    if (command.action === 'reserve') {
      if (now >= current.deadlineAt || pending || current.chargedProviderDispatches >= current.maxProviderDispatches) reject('deadline, pending fence or dispatch budget exhausted')
      if (next.runs.some(run => run.attempts.some(item => item.id === command.attemptId)) || next.receipts.length + 3 > L.receipts) reject('attempt identity or settlement capacity exhausted')
      current.attempts.push({ id: command.attemptId, reservedAt: now }); current.chargedProviderDispatches++
    } else if (command.action === 'settle') {
      if (!pending || pending.id !== command.attemptId) reject('attempt is not the current pending reservation')
      pending.outcome = structuredClone(command.outcome); pending.settledAt = now
      if (command.outcome.state === 'unknown') current.status = 'unknown'
    } else if (command.action === 'orphan') {
      if (pending) { pending.outcome = { state: 'unknown', charged: true, grantsPermission: false }; pending.settledAt = now }
      current.status = 'unknown' // Even an idle unfinished run must not regain execution authority after reopen.
    } else {
      if (pending) reject('pending reservation must be settled before finish')
      current.status = 'finished' // NOT goal/model/business completion.
    }
    current.updatedAt = now
  }
  next.revision++
  const receipt: DispatchLedgerOperationReceipt = { action: command.action, operationHash, digest, revision: next.revision, runId: command.runId, ...('attemptId' in command ? { attemptId: command.attemptId } : {}) }
  next.receipts.push(receipt); validateDispatchLedger(next)
  if (['begin', 'reserve'].includes(command.action) && Buffer.byteLength(JSON.stringify(next), 'utf8') > L.plainBytes - L.settlementHeadroom) reject('settlement byte headroom exhausted')
  return { document: next, receipt: structuredClone(receipt), replay: false }
}
